"""
Curated core table — the ~200 foods people log most often in Israel.

Each entry names WHERE its numbers come from; build_curated.py copies the
values from that record (it never types a nutrient by hand):

  'moh:<code>'   Israeli Ministry of Health national nutrition DB (Tzameret),
                 data.gov.il, per 100 g
  'fdc:<id>'     USDA FoodData Central (Foundation / SR Legacy), per 100 g
  'off:<barcode>' Open Food Facts product page (manufacturer label as entered
                 by contributors) — only for specific Israeli branded products
  R([...])       standard recipe computed from referenced ingredients
                 (grams of each ingredient, as eaten)
  EST(...)       no reliable source found: typical values, flagged "estimate"

`alt` lists other records for the same food; the build compares them and
reports discrepancies > 15 % (docs/food-data/curated-report.md).

units: grams per unit word; `serving` is the default portion when no amount
is given. Unit weights come from the referenced record's serving table where
it has a sensible one, otherwise from the previous table (marked in report).
"""

def R(parts, note=''):
    return {'recipe': parts, 'note': note}

def EST(kcal, p, f, c, note):
    return {'estimate': [kcal, p, f, c], 'note': note}

def E(key, he, en, emoji, aliases, state, ref, units, **kw):
    return dict(key=key, he=he, en=en, emoji=emoji, aliases=aliases, state=state, ref=ref, units=units, **kw)

